def add_default_scoring_settings(apps, schema_editor):
    Group = apps.get_model("tipping", "Group")
    GroupScoringSettings = apps.get_model(
        "tipping",
        "GroupScoringSettings",
    )
    Prediction = apps.get_model("tipping", "Prediction")

    first_predictions = {
        row["group_id"]: row["first_prediction_at"]
        for row in (
            Prediction.objects
            .filter(
                pred_home__isnull=False,
                pred_away__isnull=False,
            )
            .values("group_id")
            .annotate(
                first_prediction_at=Min("updated_at"),
            )
        )
    }
    now = timezone.now()

    GroupScoringSettings.objects.bulk_create(
        [
            GroupScoringSettings(
                group_id=group_id,
                exact_points=4,
                goal_difference_points=3,
                tendency_points=2,
                incorrect_points=0,
                locked_at=first_predictions.get(group_id),
                created_at=now,
                updated_at=now,
            )
            for group_id in Group.objects.values_list(
                "id",
                flat=True,
            )
        ],
        batch_size=1000,
    )

    pending_updates = []

    for prediction in (
        Prediction.objects
        .select_related("match")
        .all()
        .iterator(chunk_size=1000)
    ):
        match = prediction.match

        if (
            match.home_score is None
            or match.away_score is None
            or prediction.pred_home is None
            or prediction.pred_away is None
        ):
            category = None
        elif (
            prediction.pred_home == match.home_score
            and prediction.pred_away == match.away_score
        ):
            category = "exact"
        elif (
            prediction.pred_home - prediction.pred_away
            == match.home_score - match.away_score
        ):
            category = "goal_difference"
        else:
            predicted_tendency = (
                (prediction.pred_home > prediction.pred_away)
                - (prediction.pred_home < prediction.pred_away)
            )
            actual_tendency = (
                (match.home_score > match.away_score)
                - (match.home_score < match.away_score)
            )
            category = (
                "tendency"
                if predicted_tendency == actual_tendency
                else "incorrect"
            )

        prediction.score_category = category
        pending_updates.append(prediction)

        if len(pending_updates) >= 1000:
            Prediction.objects.bulk_update(
                pending_updates,
                ["score_category"],
                batch_size=1000,
            )
            pending_updates = []

    if pending_updates:
        Prediction.objects.bulk_update(
            pending_updates,
            ["score_category"],
            batch_size=1000,
        )


